import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyConsultationScreen extends StatefulWidget{const PregnancyConsultationScreen({super.key});@override State<PregnancyConsultationScreen>createState()=>_S();}class _S extends State<PregnancyConsultationScreen>{final q=TextEditingController();bool saving=false;@override void dispose(){q.dispose();super.dispose();}Future<void>send()async{final u=FirebaseAuth.instance.currentUser;if(u==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('سجل الدخول أولاً')));return;}if(q.text.trim().isEmpty)return;setState(()=>saving=true);try{await PregnancyService().createConsultation(userId:u.uid,question:q.text.trim());q.clear();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال الاستشارة')));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('استشارة الحمل')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[TextField(controller:q,maxLines:6,decoration:const InputDecoration(labelText:'اكتب سؤالك',border:OutlineInputBorder())),const SizedBox(height:16),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:saving?null:send,child:Text(saving?'جارٍ الإرسال...':'إرسال الاستشارة')))])));}}
